CREATE POLICY "interruption parent ownership" ON public.interruptions AS RESTRICTIVE FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.focus_sessions f WHERE f.id=session_id AND f.user_id=auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.focus_sessions f WHERE f.id=session_id AND f.user_id=auth.uid()));
CREATE POLICY "skip parent ownership" ON public.recurring_skips AS RESTRICTIVE FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.recurring_blocks b WHERE b.id=block_id AND b.user_id=auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.recurring_blocks b WHERE b.id=block_id AND b.user_id=auth.uid()));
CREATE OR REPLACE FUNCTION public.lock_invitation_removal() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(lower(OLD.email),0)); RETURN OLD; END $$;
REVOKE ALL ON FUNCTION public.lock_invitation_removal() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER lock_invitation_removal BEFORE DELETE ON public.allowed_emails FOR EACH ROW EXECUTE FUNCTION public.lock_invitation_removal();
CREATE OR REPLACE FUNCTION public.validate_member_admission() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth AS $$ DECLARE account_email text; BEGIN IF NEW.role='member' THEN SELECT lower(email) INTO account_email FROM auth.users WHERE id=NEW.user_id; PERFORM pg_advisory_xact_lock(hashtextextended(account_email,0)); IF NOT EXISTS(SELECT 1 FROM public.allowed_emails WHERE lower(email)=account_email) THEN RAISE EXCEPTION 'Invitation unavailable'; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_member_admission() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER validate_member_admission BEFORE INSERT OR UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.validate_member_admission();